## 任务管理器

```javascript
const taskManager = {
  tasks: [],
  queue: [],
  running: 0,
  maxConcurrent: 2,

  create(config) { ... },
  getById(id) { ... },
  processQueue() { ... },
  async runTask(task) { ... },
  updateCard(task) { ... },
  renderList() { ... },
  cancelTask(task) { ... },
  clearAll() { ... }
};
```

### create

创建任务对象，推入 `tasks` 和 `queue`，触发队列处理。

### processQueue

核心调度：

```javascript
processQueue() {
  while (this.running < this.maxConcurrent && this.queue.length > 0) {
    const task = this.queue.shift();
    if (task.deleted) continue;

    this.running++;
    task.status = 'generating';
    this.updateCard(task);

    this.runTask(task).finally(() => {
      this.running--;
      this.processQueue();
    });
  }

  // 更新剩余任务的排队位置
  this.queue.forEach((t, i) => {
    t.queuePosition = i + 1;
    t.status = 'queued';
    this.updateCard(t);
  });

  this.renderList();
}
```

### runTask

单个任务的完整生命周期：

```javascript
async runTask(task) {
  task.abortController = new AbortController();
  this.updateCard(task);

  try {
    const { content, reasoning, finishReason } = await streamTask(task);

    task.contentRaw = content;
    task.reasoningRaw = reasoning;
    task.finishReason = finishReason;

    let finalText = /* 选择字段 */;
    let parsed = parseJsonResult(finalText);

    const check = detectTruncation(parsed);
    if (check.truncated) {
      parsed.html = fixTruncatedHtml(parsed.html);
      if (detectTruncation(parsed).truncated) {
        throw new Error('产物截断且无法修复');
      }
    }

    task.title = parsed.title;
    task.duration = parsed.duration;
    task.html = parsed.html;
    task.status = 'completed';
    this.updateCard(task);
    saveCompleted();

    captureCover(task.html).then(url => {
      if (url) {
        task.cover = url;
        this.updateCard(task);
        saveCompleted();
      }
    });
  } catch (e) {
    if (task.deleted) return;
    task.status = e.name === 'AbortError' ? 'aborted' : 'failed';
    task.error = e.message;
    this.updateCard(task);
  }
}
```

## 主题引擎

### 颜色派生

```javascript
apply() {
  const { h, s } = hexToHsl(this.primaryColor);
  const isDark = this.current === 'dark';

  const surfaceHex = isDark
    ? hslToHex(h, s * 0.15, 8)
    : hslToHex(h, s * 0.15, 97);

