## JSON 解析

```javascript
function parseJsonResult(raw) {
  let text = (raw || '').trim();

  // 1. 剥离 markdown 代码块
  const md = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (md) text = md[1].trim();

  // 2. 直接解析
  let obj = tryParseJson(text);
  if (obj && (obj.html || obj.title)) return normalize(obj);

  // 3. 截取花括号范围
  const s = text.indexOf('{'), e = text.lastIndexOf('}');
  if (s >= 0 && e > s) {
    obj = tryParseJson(text.slice(s, e + 1));
    if (obj && (obj.html || obj.title)) return normalize(obj);
  }

  // 4. 宽松提取
  const html = extractHtmlLenient(text);
  if (html) {
    return {
      title: extractStringField(text, 'title') || '未命名视频',
      duration: extractNumberField(text, 'duration') || 5,
      cover_colors: null,
      html
    };
  }

  throw new Error('无法解析 JSON 响应');
}
```

